async ({ http: { request } }) => {
  const u = "https://github.com/user-attachments/files/34935078/2000.vs.2026.Market.Overlay.html";
  const b = (await request(u, { maxBytes: 1_000_000, headers: { "User-Agent": "Mozilla/5.0" } })).body;
  const text = b.replace(/<script[\s\S]*?<\/script>/g, " ").replace(/<style[\s\S]*?<\/style>/g, " ").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
  const scripts = [...b.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].map((m) => m[1]);
  const info = scripts.map((s) => ({ len: s.length, head: s.slice(0, 600), vars: [...s.matchAll(/(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=/g)].map((m) => m[1]).slice(0, 40) }));
  // find functions related to fit/correlation/anchor
  const all = scripts.join("\n");
  const snippets = ["corr", "anchor", "bestFit", "best", "catalyst", "ANCHOR", "peak"].map((k) => { const i = all.indexOf(k); return { k, at: i, s: i >= 0 ? all.slice(Math.max(0, i - 200), i + 500) : null }; });
  return { tail: text.slice(3900, 7000), nScripts: scripts.length, info, snippets } as PitJsonValue;
}
